import{_ as o,o as t,c as p,a4 as a}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-090","description":"","frontmatter":{"date":"2020-10-22T19:37:59","title":"写作课作业-090","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/090.md","filePath":"posts/homework/090.md"}'),l={name:"posts/homework/090.md"};function r(c,e,s,i,n,u){return t(),p("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《微信互联网平民创业》之《22.如何成为真正赢得起的人?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>「失败并不可怕，真正可怕的是，差一点就成功了——但终究还是没成功……」</p></blockquote><blockquote><p>人们常常嘲笑他人「输不起」，殊不知，真正残酷的是「赢不起」。「差一点成功却终究没有成功」的本质就是「赢不起」——因为你的实力不够赢，因为哪怕运气也是实力之一。</p></blockquote><blockquote><p>价值这个东西总是需要很久的时间才能被发现……</p><p>无论干啥，无论干得多好，都值得干得更久一点——越是往后越是有惊人的收获。</p></blockquote><blockquote><p>真正骇人，甚至害人的是：</p><p>赚到很多钱知乎自己却惊人因此变傻了……</p></blockquote><blockquote><p>把自己的时间投入到「创造价值」之中……也就是要把时间投入到我们之前就提到过的「提升自己的价值力」上。</p></blockquote><blockquote><p>金钱和时间，都是排他性资源，都是用来干这个就不能同时用来干那个的东西。金钱有两个用处——一个是消费，一个是投资。时间也有两个用处，一个是消费，另一个是「创造价值」</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>之前的领导，在我们中时常会提一个和他同期的同事，这位前辈呢，比较爱跳槽，跳来跳去都不是太如意，反而不如他们这一期中一起留下来的人都做到管理岗位了，收入什么的也都不错。当时他主要是想告诉我们做一件事情要沉下心来，慢慢做出成绩。现在想来自己也跳了几家公司了，看看和我同期在还在公司的也挺好。</p><p>因为离职，没在医疗行业了，需要积累新的行业知识，一切似乎都是从头开始，但也因为脱离了岗位，编码的时间多了起来，积累不同行业的经验，似乎也没什么不好。现在这么说似乎有酸葡萄心理，似乎就是「输不起」，未来还很长不是吗？</p><p>相信自己投入的时间产生收获的。</p><p>每每看到「相信我，你并不孤独」，就觉得这句话特别有力量。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',20)])])}const d=o(l,[["render",r]]);export{_ as __pageData,d as default};
